INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1', NULL, NULL, 'topic_analysis', 'Please analyze the following trend:\n\nTREND KEYWORD: NEET 2026 Counselling Dates\n\nSOURCE INFORMATION:\nSource Name: MCC\nSource URL: https://mcc.nic.in\nSource Snippet: Not specified\n\n\nEXISTING RELATED ARTICLES IN OUR DATABASE:\n- None\n\nReturn your response strictly as a JSON object with this exact schema:\n{\n  \"publish_recommendation\": true/false,\n  \"category\": \"category-slug-from-allowed-list\",\n  \"search_intent\": \"informational | direct_action | deadline_tracking | comparison\",\n  \"priority_score\": 8', '{\"publish_recommendation\":true,\"category\":\"exam-results\",\"search_intent\":\"direct_action\",\"priority_score\":92,\"article_type\":\"breaking_notice\",\"required_source_type\":\"statutory_authority\",\"suggested_original_angle\":\"Step-by-step AIQ choice filling instructions\",\"duplicate_risk\":\"low\",\"reasoning\":\"Official MCC schedule released today.\"}', '100', '1', NULL, '2026-08-18 16:41:19');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('2', NULL, NULL, 'article_generation', 'Please generate an original, comprehensive editorial report based strictly on the following verified information:\n\nTOPIC / HEADLINE: NEET UG 2026 Round 1 Counselling Schedule\nCATEGORY: exam-results\nEDITORIAL FOCUS: Step-by-step choice filling\n\nVERIFIED SOURCE DATA & OFFICIAL FACTS:\n{\n    \"dates\": \"August 20 - 24, 2026\",\n    \"authority\": \"MCC\",\n    \"quota\": \"15% AIQ\"\n}\n\nReturn your output strictly as a JSON object with this exact schema:\n{\n  \"title\": \"Clear, informative headline under 75 characte', '{\"title\":\"NEET UG 2026 Round 1 AIQ Counselling Schedule Released: Key Dates\",\"excerpt\":\"MCC has released the complete Round 1 schedule for 15% AIQ MBBS seats. Registration begins August 20.\",\"content\":\"<h2>Official Counselling Schedule<\\/h2><p>The Medical Counselling Committee has issued the confirmed timetable for NEET UG 2026 admissions.<\\/p><h2>Important Instructions<\\/h2><ul><li>Register on official portal<\\/li><li>Verify choice locking<\\/li><\\/ul>\",\"key_takeaways\":[\"Round 1 registration opens August 20, 2026\",\"Choice locking window closes August 24, 2026\",\"Seat allotment results on August 27, 2026\"],\"dates_table\":[{\"event\":\"Registration Window\",\"date\":\"August 20 - 24, 2026\",\"status\":\"confirmed\"},{\"event\":\"Seat Allotment\",\"date\":\"August 27, 2026\",\"status\":\"confirmed\"}],\"source_attribution\":{\"name\":\"Medical Counselling Committee (MCC)\",\"url\":\"https:\\/\\/mcc.nic.in\",\"reference\":\"Ref No. U-12021\\/01\\/2026-MEC\"}}', '100', '1', NULL, '2026-08-18 16:41:19');
