INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('223', NULL, NULL, 'article_generation', 'Please generate an original, comprehensive editorial report based strictly on the following verified information:\n\nTOPIC / HEADLINE: NEET UG 2026 Round 1 Counselling Schedule\nCATEGORY: exam-results\nEDITORIAL FOCUS: Step-by-step choice filling\n\nVERIFIED SOURCE DATA & OFFICIAL FACTS:\n{\n    \"dates\": \"August 20 - 24, 2026\",\n    \"authority\": \"MCC\",\n    \"quota\": \"15% AIQ\"\n}\n\nReturn your output strictly as a JSON object with this exact schema:\n{\n  \"title\": \"Clear, informative headline under 75 characte', '{\"title\":\"NEET UG 2026 Round 1 AIQ Counselling Schedule Released: Key Dates\",\"excerpt\":\"MCC has released the complete Round 1 schedule for 15% AIQ MBBS seats. Registration begins August 20.\",\"content\":\"<h2>Official Counselling Schedule<\\/h2><p>The Medical Counselling Committee has issued the confirmed timetable for NEET UG 2026 admissions.<\\/p><h2>Important Instructions<\\/h2><ul><li>Register on official portal<\\/li><li>Verify choice locking<\\/li><\\/ul>\",\"key_takeaways\":[\"Round 1 registration opens August 20, 2026\",\"Choice locking window closes August 24, 2026\",\"Seat allotment results on August 27, 2026\"],\"dates_table\":[{\"event\":\"Registration Window\",\"date\":\"August 20 - 24, 2026\",\"status\":\"confirmed\"},{\"event\":\"Seat Allotment\",\"date\":\"August 27, 2026\",\"status\":\"confirmed\"}],\"source_attribution\":{\"name\":\"Medical Counselling Committee (MCC)\",\"url\":\"https:\\/\\/mcc.nic.in\",\"reference\":\"Ref No. U-12021\\/01\\/2026-MEC\"}}', '100', '1', NULL, '2026-08-18 16:56:33');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('224', '1', NULL, 'fact_checking', 'Please perform a rigorous factual audit on the following draft article:\n\nDRAFT ARTICLE TITLE:\nNEET UG 2026 Round 1 AIQ Counselling Schedule Released: Key Dates\n\nDRAFT ARTICLE CONTENT:\nOfficial Counselling ScheduleThe Medical Counselling Committee has issued the confirmed timetable for NEET UG 2026 admissions.Important InstructionsRegister on official portalVerify choice locking\n\nGROUND TRUTH SOURCE DATA:\n{\n    \"authority\": \"MCC\",\n    \"date\": \"August 20, 2026\"\n}\n\nReturn your audit strictly as a J', '{\"overall_score\":96,\"factual_accuracy_score\":98,\"dates_accuracy_score\":97,\"source_consistency_score\":95,\"hallucination_risk\":\"low\",\"copied_risk\":\"low\",\"recommendation\":\"pass\",\"flagged_issues\":[],\"summary\":\"All dates and MCC authority credentials perfectly align with official bulletin.\"}', '100', '1', NULL, '2026-08-18 16:56:33');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('225', NULL, NULL, 'seo_generation', 'Please generate SEO metadata for this article:\n\nARTICLE TITLE: NEET UG 2026 Round 1 AIQ Counselling Schedule Released: Key Dates\nCATEGORY: exam-results\nARTICLE CONTENT EXCERPT:\nOfficial Counselling ScheduleThe Medical Counselling Committee has issued the confirmed timetable for NEET UG 2026 admissions.Important InstructionsRegister on official portalVerify choice locking\n\nReturn your response strictly as a JSON object with this exact schema:\n{\n  \"seo_title\": \"Optimized meta title under 60 charac', '{\"seo_title\":\"NEET UG 2026 Counselling Dates Released: Check AIQ Schedule\",\"meta_description\":\"MCC has declared the official NEET UG 2026 Round 1 counselling dates. Check registration deadlines, eligibility, and seat allotment schedule.\",\"slug_suggestion\":\"neet-ug-2026-counselling-dates-schedule\",\"excerpt\":\"MCC declares official Round 1 MBBS\\/BDS counselling dates starting August 20.\",\"faqs\":[{\"question\":\"When does NEET UG 2026 Round 1 registration start?\",\"answer\":\"Registration commences on August 20, 2026, on the official MCC portal.\"}]}', '100', '1', NULL, '2026-08-18 16:56:33');
