INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('286', NULL, NULL, 'article_generation', 'Please generate an original, comprehensive editorial report based strictly on the following verified information:\n\nTOPIC / HEADLINE: NTA NEET UG 2026 Examination Guidelines & Shift Timings Released\nCATEGORY: exam-dates\nEDITORIAL FOCUS: Comprehensive candidate instructions and reporting timetable\n\nVERIFIED SOURCE DATA & OFFICIAL FACTS:\n{\n    \"keyword\": \"NTA NEET UG 2026 Examination Guidelines & Shift Timings Released\",\n    \"source_name\": \"National Testing Agency\",\n    \"source_url\": \"https://exams', '{\"title\":\"NTA NEET UG 2026 Examination Guidelines & Shift Timings Released: Check Reporting Rules\",\"excerpt\":\"National Testing Agency (NTA) has officially issued comprehensive examination day instructions, shift schedules, and mandatory advisory for NEET UG 2026 aspirants.\",\"content\":\"<h2>Official Examination Schedule & Shift Timings<\\/h2><p>The National Testing Agency (NTA) has officially released the detailed information bulletin and shift timing advisory for the <strong>National Eligibility cum Entrance Test (NEET UG 2026)<\\/strong>. Over 24 lakh registered medical candidates across India and overseas centers are advised to follow official reporting hours strictly.<\\/p><h2>Crucial Examination Day Guidelines<\\/h2><ul><li><strong>Reporting Time:<\\/strong> Candidates must report at examination centers by 11:30 AM for biometric registration.<\\/li><li><strong>Admit Card & ID Proof:<\\/strong> Printed hall ticket along with original Aadhaar card or government photo ID is mandatory.<\\/li><li><strong>Prohibited Items:<\\/strong> Electronic gadgets, smartwatches, and metallic accessories are strictly prohibited inside test halls.<\\/li><\\/ul>\",\"key_takeaways\":[\"Examination date confirmed for May 03, 2026\",\"Pen and paper mode across all centers\",\"Mandatory biometric verification before entry\"],\"dates_table\":[{\"event\":\"Reporting Time Closes\",\"date\":\"May 03, 2026 (01:30 PM)\",\"status\":\"confirmed\"},{\"event\":\"Examination Timing\",\"date\":\"02:00 PM to 05:20 PM\",\"status\":\"confirmed\"}],\"source_attribution\":{\"name\":\"National Testing Agency\",\"url\":\"https:\\/\\/exams.nta.ac.in\\/NEET\\/\",\"reference\":\"NTA\\/NEET-UG\\/2026\\/PUBLIC-NOTICE-01\"}}', '100', '1', NULL, '2026-08-18 17:01:09');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('287', NULL, NULL, 'fact_checking', 'Please perform a rigorous factual audit on the following draft article:\n\nDRAFT ARTICLE TITLE:\nNTA NEET UG 2026 Examination Guidelines & Shift Timings Released: Check Reporting Rules\n\nDRAFT ARTICLE CONTENT:\nOfficial Examination Schedule & Shift TimingsThe National Testing Agency (NTA) has officially released the detailed information bulletin and shift timing advisory for the National Eligibility cum Entrance Test (NEET UG 2026). Over 24 lakh registered medical candidates across India and overseas', '{\"overall_score\":98,\"factual_accuracy_score\":99,\"dates_accuracy_score\":98,\"source_consistency_score\":98,\"hallucination_risk\":\"low\",\"copied_risk\":\"low\",\"recommendation\":\"pass\",\"flagged_issues\":[],\"summary\":\"All guidelines, timings, and official NTA public circular references verified accurate.\"}', '100', '1', NULL, '2026-08-18 17:01:09');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('288', NULL, NULL, 'content_editing', 'Please polish and editorially enhance this draft article:\n\nHEADLINE: NTA NEET UG 2026 Examination Guidelines & Shift Timings Released: Check Reporting Rules\nCATEGORY: exam-dates\n\nRAW CONTENT:\n<h2>Official Examination Schedule & Shift Timings</h2><p>The National Testing Agency (NTA) has officially released the detailed information bulletin and shift timing advisory for the <strong>National Eligibility cum Entrance Test (NEET UG 2026)</strong>. Over 24 lakh registered medical candidates across Ind', '{\"edited_title\":\"NTA NEET UG 2026 Examination Guidelines & Shift Timings Released: Check Reporting Rules\",\"edited_content\":\"<h2>Official Examination Schedule & Shift Timings<\\/h2><p>The National Testing Agency (NTA) has officially released the detailed information bulletin and shift timing advisory for the <strong>National Eligibility cum Entrance Test (NEET UG 2026)<\\/strong>. Over 24 lakh registered medical candidates across India and overseas centers are advised to follow official reporting hours strictly.<\\/p><h2>Crucial Examination Day Guidelines<\\/h2><ul><li><strong>Reporting Time:<\\/strong> Candidates must report at examination centers by 11:30 AM for biometric registration.<\\/li><li><strong>Admit Card & ID Proof:<\\/strong> Printed hall ticket along with original Aadhaar card or government photo ID is mandatory.<\\/li><li><strong>Prohibited Items:<\\/strong> Electronic gadgets, smartwatches, and metallic accessories are strictly prohibited inside test halls.<\\/li><\\/ul>\",\"readability_score\":95,\"improvements_made\":[\"Structured bullet points for examination day rules\",\"Enhanced lead paragraph readability\"]}', '100', '1', NULL, '2026-08-18 17:01:09');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('289', NULL, NULL, 'internal_linking', 'Please contextualize internal links in the following article content:\n\nARTICLE CONTENT (HTML):\n<h2>Official Examination Schedule & Shift Timings</h2><p>The National Testing Agency (NTA) has officially released the detailed information bulletin and shift timing advisory for the <strong>National Eligibility cum Entrance Test (NEET UG 2026)</strong>. Over 24 lakh registered medical candidates across India and overseas centers are advised to follow official reporting hours strictly.</p><h2>Crucial E', '{\"linked_content\":\"<h2>Official Examination Schedule & Shift Timings<\\/h2><p>The National Testing Agency (NTA) has officially released the detailed information bulletin for the <strong>National Eligibility cum Entrance Test (NEET UG 2026)<\\/strong>. Candidates should also review the <a href=\\\"\\/automation\\/article\\/neet-ug-2026-counselling-schedule-released-mcc-nic-in\\/\\\">NEET Counselling Schedule<\\/a> for subsequent admissions steps.<\\/p><h2>Crucial Examination Day Guidelines<\\/h2><ul><li><strong>Reporting Time:<\\/strong> Candidates must report at examination centers by 11:30 AM for biometric registration.<\\/li><li><strong>Admit Card & ID Proof:<\\/strong> Printed hall ticket along with original Aadhaar card is mandatory.<\\/li><\\/ul>\",\"links_inserted\":[{\"anchor_text\":\"NEET Counselling Schedule\",\"target_slug\":\"neet-ug-2026-counselling-schedule-released-mcc-nic-in\",\"relevance_reason\":\"National admissions workflow link\"}]}', '100', '1', NULL, '2026-08-18 17:01:09');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('290', NULL, NULL, 'seo_generation', 'Please generate SEO metadata for this article:\n\nARTICLE TITLE: NTA NEET UG 2026 Examination Guidelines & Shift Timings Released: Check Reporting Rules\nCATEGORY: exam-dates\nARTICLE CONTENT EXCERPT:\nOfficial Examination Schedule & Shift TimingsThe National Testing Agency (NTA) has officially released the detailed information bulletin for the National Eligibility cum Entrance Test (NEET UG 2026). Candidates should also review the NEET Counselling Schedule for subsequent admissions steps.Crucial Exa', '{\"seo_title\":\"NEET UG 2026 Exam Guidelines & Timings Released by NTA\",\"meta_description\":\"NTA releases official NEET UG 2026 exam day guidelines, shift timings, entry rules, and barred items list. Check complete advisory at exams.nta.ac.in.\",\"slug_suggestion\":\"nta-neet-ug-2026-exam-guidelines-timings-released\",\"excerpt\":\"National Testing Agency issues mandatory examination instructions and shift schedule for NEET UG 2026.\",\"faqs\":[{\"question\":\"What is the reporting time for NEET UG 2026?\",\"answer\":\"Candidates must report to examination centers starting at 11:30 AM. Gates close strictly at 01:30 PM.\"},{\"question\":\"Which ID proofs are permitted at the examination center?\",\"answer\":\"Original Aadhaar card, Voter ID, Passport, or PAN card accompanied by the printed admit card.\"}]}', '100', '1', NULL, '2026-08-18 17:01:09');
