INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('728', NULL, NULL, 'seo_generation', 'Please generate SEO metadata for this article:\n\nARTICLE TITLE: NTA NEET UG 2026 Examination Guidelines & Shift Timings Released: Check Reporting Rules\nCATEGORY: exam-dates\nARTICLE CONTENT EXCERPT:\nOfficial Examination Schedule & Shift TimingsThe National Testing Agency (NTA) has officially released the detailed information bulletin and shift timing advisory for the National Eligibility cum Entrance Test (NEET UG 2026). Over 24 lakh registered medical candidates across India and overseas centers ', '{\"seo_title\":\"NEET UG 2026 Exam Guidelines & Timings Released by NTA\",\"meta_description\":\"NTA releases official NEET UG 2026 exam day guidelines, shift timings, entry rules, and barred items list. Check complete advisory at exams.nta.ac.in.\",\"slug_suggestion\":\"nta-neet-ug-2026-exam-guidelines-timings-released\",\"excerpt\":\"National Testing Agency issues mandatory examination instructions and shift schedule for NEET UG 2026.\",\"faqs\":[{\"question\":\"What is the reporting time for NEET UG 2026?\",\"answer\":\"Candidates must report to examination centers starting at 11:30 AM. Gates close strictly at 01:30 PM.\"},{\"question\":\"Which ID proofs are permitted at the examination center?\",\"answer\":\"Original Aadhaar card, Voter ID, Passport, or PAN card accompanied by the printed admit card.\"}]}', '100', '1', NULL, '2026-08-20 16:21:39');
