INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('792', NULL, NULL, 'topic_analysis', 'Please analyze the following trend:\n\nTREND KEYWORD: IBPS PO 2026 Selection Process: Prelims, Mains & Interview Score Normalization Rules\n\nSOURCE INFORMATION:\nSource Name: Institute of Banking Personnel Selection (IBPS)\nSource URL: https://ibps.in\nSource Snippet: {\"source_type\":\"evergreen_official\",\"authority\":\"Institute of Banking Personnel Selection (IBPS)\",\"url\":\"https:\\/\\/ibps.in\"}\n\n\nEXISTING RELATED ARTICLES IN OUR DATABASE:\n- CBSE CTET 2026 Notification: Eligibility, Application Process, Ex', '{\n  \"publish_recommendation\": true,\n  \"category\": \"government-jobs\",\n  \"search_intent\": \"informational\",\n  \"priority_score\": 78,\n  \"article_type\": \"comprehensive_guide\",\n  \"required_source_type\": \"statutory_authority\",\n  \"suggested_original_angle\": \"Detailed breakdown of the equipercentile normalization method in multi-shift Prelims, along with the step-by-step 80:20 Mains-to-Interview final merit list score calculation formula.\",\n  \"duplicate_risk\": \"low\",\n  \"reasoning\": \"Existing database articles cover the IBPS PO admit card release, but lack a dedicated breakdown of the selection stages and score normalization mechanics. Providing clear explanations of shift normalization and weightage calculations offers substantial actionable clarity for banking candidates.\"\n}', '1552', '1', NULL, '2026-08-21 09:40:47');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('793', NULL, NULL, 'topic_analysis', 'Please analyze the following trend:\n\nTREND KEYWORD: Railway RRB NTPC 2026 Computer Based Aptitude Test (CBAT) Guidelines & Scoring\n\nSOURCE INFORMATION:\nSource Name: Railway Recruitment Control Board (RRB)\nSource URL: https://rrbcdg.gov.in\nSource Snippet: {\"source_type\":\"evergreen_official\",\"authority\":\"Railway Recruitment Control Board (RRB)\",\"url\":\"https:\\/\\/rrbcdg.gov.in\"}\n\n\nEXISTING RELATED ARTICLES IN OUR DATABASE:\n- CBSE CTET 2026 Notification: Eligibility, Application Process, Exam Pattern', '{\n  \"publish_recommendation\": true,\n  \"category\": \"government-jobs\",\n  \"search_intent\": \"informational\",\n  \"priority_score\": 85,\n  \"article_type\": \"comprehensive_guide\",\n  \"required_source_type\": \"government_portal\",\n  \"suggested_original_angle\": \"Step-by-step decoding of T-score calculation, the 5 test batteries, zero negative marking rule, and official RDSO guidelines for RRB NTPC candidates.\",\n  \"duplicate_risk\": \"low\",\n  \"reasoning\": \"No existing articles in the database cover RRB NTPC CBAT (Psycho Test) guidelines. Explaining the T-score normalized scoring system (42 cutoff per battery) directly meets high candidate search demand with structured, actionable insights.\"\n}', '1944', '1', NULL, '2026-08-21 09:41:00');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('794', NULL, NULL, 'article_generation', 'Please generate an in-depth, exhaustive, AdSense-ready editorial article (aim for 1000+ words) based strictly on the following verified information:\n\nTOPIC / HEADLINE: CBSE CTET 2026 Official Notification & Registration Schedule Announced at ctet.nic.in\nCATEGORY: entrance-exams\nEDITORIAL FOCUS: Comprehensive student instructions\n\nVERIFIED SOURCE DATA & OFFICIAL FACTS:\n{\n    \"keyword\": \"CBSE CTET 2026 Official Notification & Registration Schedule Announced at ctet.nic.in\",\n    \"source_name\": \"Cen', '{\n  \"title\": \"CBSE CTET 2026 Notification Released: Registration Schedule & Guidelines\",\n  \"excerpt\": \"CBSE has officially announced the CTET 2026 notification and registration schedule. Eligible candidates can apply online at ctet.nic.in following official norms.\",\n  \"content\": \"<h2>Comprehensive Overview & Official Announcement Details</h2><p>The Central Board of Secondary Education (CBSE) has formally released the official notification and online registration schedule for the Central Teacher Eligibility Test (CTET) 2026. Aspirants across India seeking eligibility for teaching positions in primary (Classes I to V) and upper primary (Classes VI to VIII) stages can now access the official information bulletin directly from the dedicated portal, <strong>ctet.nic.in</strong>. CTET is conducted in accordance with the regulatory standards prescribed by the National Council for Teacher Education (NCTE), serving as a benchmark benchmark qualification for prospective educators.</p><p>Holding a valid CTET certificate is a mandatory prerequisite for candidates aiming to secure teaching employment in central government institutions, including Kendriya Vidyalayas (KVS), Navodaya Vidyalayas (NVS), Central Tibetan Schools, and schools under the administrative control of Union Territories (UTs) such as Delhi, Chandigarh, Dadra & Nagar Haveli, Daman & Diu, Lakshadweep, and Andaman & Nicobar Islands. Furthermore, private schools and state government-aided bodies frequently consider CTET scores during their recruitment and selection procedures. The assessment is structured into two primary papers: Paper-I for candidates intending to teach Classes I to V, and Paper-II for those intending to teach Classes VI to VIII. Candidates fulfilling the statutory requirements for both levels are eligible to appear in both papers.</p><h2>Important Dates, Timetable & Official Deadlines</h2><p>CBSE has detailed the complete schedule for the submission of online applications, fee payments, document ', '6208', '1', NULL, '2026-08-21 09:42:01');
