INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1059', NULL, NULL, 'article_update', 'You are a senior Indian education news editor at Sarkari.online, an independent education and recruitment platform.\nWe have an existing published article that may need an incremental factual update based on new official releases.\n\nRULES:\n- NEVER rewrite an article just to make it look fresh.\n- ONLY modify sections affected by verified new facts (e.g. date change, result declared, link active, corrigendum).\n- PRESERVE the existing structure, clarity, and tone.\n- If there are NO meaningful changes', '{\"has_meaningful_update\":true,\"update_type\":\"corrigendum\",\"change_summary\":\"NTA issued revised advisory confirming additional test center cities in Middle East for NEET UG 2026\",\"proposed_title\":\"NTA NEET UG 2026 Exam Guidelines & Overseas Center List Released\",\"proposed_excerpt\":\"NTA updates NEET UG 2026 advisory with foreign examination centers list.\",\"proposed_content\":\"<h2>Official Examination Schedule & Overseas Centers<\\/h2><p>The National Testing Agency (NTA) has officially updated the information bulletin for <strong>NEET UG 2026<\\/strong>, confirming foreign test centers across 14 international cities alongside domestic centers.<\\/p>\"}', '100', '1', NULL, '2026-08-21 15:49:58');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1060', NULL, NULL, 'fact_checking', 'Please perform a rigorous factual audit on the following draft article:\n\nDRAFT ARTICLE TITLE:\nNTA NEET UG 2026 Exam Guidelines & Overseas Center List Released\n\nDRAFT ARTICLE CONTENT:\nOfficial Examination Schedule & Overseas CentersThe National Testing Agency (NTA) has officially updated the information bulletin for NEET UG 2026, confirming foreign test centers across 14 international cities alongside domestic centers.\n\nGROUND TRUTH SOURCE DATA:\n{\n    \"source_name\": \"National Testing Agency\",\n   ', '{\"overall_score\":98,\"factual_accuracy_score\":99,\"dates_accuracy_score\":98,\"source_consistency_score\":98,\"hallucination_risk\":\"low\",\"copied_risk\":\"low\",\"recommendation\":\"pass\",\"flagged_issues\":[],\"summary\":\"All guidelines, timings, and official NTA public circular references verified accurate.\"}', '100', '1', NULL, '2026-08-21 15:49:58');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1061', NULL, NULL, 'topic_analysis', 'Please analyze the following trend:\n\nTREND KEYWORD: Test Malformed Topic\n\nSOURCE INFORMATION:\nSource Name: Not specified\nSource URL: Not specified\nSource Snippet: Not specified\n\n\nEXISTING RELATED ARTICLES IN OUR DATABASE:\n- None\n\nReturn your response strictly as a JSON object with this exact schema:\n{\n  \"publish_recommendation\": true/false,\n  \"category\": \"category-slug-from-allowed-list\",\n  \"search_intent\": \"informational | direct_action | deadline_tracking | comparison\",\n  \"priority_score\": 85,', 'This is plain text with no JSON brackets whatsoever', '100', '1', NULL, '2026-08-21 15:49:58');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1062', NULL, NULL, 'topic_analysis', 'Please analyze the following trend:\n\nTREND KEYWORD: स्वास्थ्य सेवा और चिकित्सा शिक्षा के लिए ईएसआईसी की अटूट प्रतिबद्धता देश को विकसित भारत की ओर अग्रसर कर रही है\n\nSOURCE INFORMATION:\nSource Name: education_rss\nSource URL: https://pib.gov.in/PressReleaseIframePage.aspx?PRID=2301624\nSource Snippet: {\"feed\":\"https:\\/\\/pi', '{\n  \"publish_recommendation\": false,\n  \"category\": \"higher-education\",\n  \"search_intent\": \"informational\",\n  \"priority_score\": 25,\n  \"article_type\": \"analysis\",\n  \"required_source_type\": \"government_portal\",\n  \"suggested_original_angle\": \"Overview of ESIC medical colleges, MBBS seat quotas for insured persons (IP quota), and upcoming healthcare infrastructure expansions.\",\n  \"duplicate_risk\": \"low\",\n  \"reasoning\": \"The press release covers general government promotional discourse regarding ESIC\'s healthcare commitments rather than delivering actionable student updates such as direct exam notices, admission seat matrices, or recruitment notifications.\"\n}', '1639', '1', NULL, '2026-08-22 04:04:24');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1063', NULL, NULL, 'topic_analysis', 'Please analyze the following trend:\n\nTREND KEYWORD: प्रधानमंत्री श्री नरेंद्र मोदी के संकल्प के अनुरूप बिहार को 11.19 लाख पक्के मकानों की केंद्रीय मंत्री श्री शिवराज सिंह चौहान ने दी सौगात, 13427 करोड़ रु. से गरीब परिवारों को मिले', '{\n  \"publish_recommendation\": false,\n  \"category\": \"government-jobs\",\n  \"search_intent\": \"informational\",\n  \"priority_score\": 10,\n  \"article_type\": \"breaking_notice\",\n  \"required_source_type\": \"government_portal\",\n  \"suggested_original_angle\": \"Not applicable as this topic falls outside the educational and career scope.\",\n  \"duplicate_risk\": \"low\",\n  \"reasoning\": \"The press release pertains to rural housing scheme allocations (Pradhan Mantri Awas Yojana) in Bihar, which is a general social welfare update and completely unrelated to education, competitive exams, admissions, scholarships, or job recruitments.\"\n}', '1908', '1', NULL, '2026-08-22 04:05:11');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1064', NULL, NULL, 'topic_analysis', 'Please analyze the following trend:\n\nTREND KEYWORD: भौतिक अवसंरचना से जनसंख्या-स्तरीय तकनीकी पहुंच तक: भारत विश्‍व के सामने परिवर्तनकारी विकास की गाथा प्रस्तुत कर रहा है : केंद्रीय संचार राज्य मंत्री डॉ. चंद्र शेखर पेम्मास', '{\n  \"publish_recommendation\": false,\n  \"category\": \"student-technology\",\n  \"search_intent\": \"informational\",\n  \"priority_score\": 20,\n  \"article_type\": \"analysis\",\n  \"required_source_type\": \"government_portal\",\n  \"suggested_original_angle\": \"Analyzing how India\'s expanding digital public infrastructure (DPI) creates long-term career opportunities in telecom, IoT, and public tech sectors for engineering and IT graduates.\",\n  \"duplicate_risk\": \"low\",\n  \"reasoning\": \"The trend is based on a general government press release highlighting India\'s digital infrastructure growth. It lacks actionable student-centric information, exam updates, admission schedules, or direct recruitment notices, making it unsuitable for an education and career intelligence portal.\"\n}', '1891', '1', NULL, '2026-08-22 04:05:16');
