INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1169', NULL, NULL, 'article_update', 'You are a senior Indian education news editor at Sarkari.online, an independent education and recruitment platform.\nWe have an existing published article that may need an incremental factual update based on new official releases.\n\nRULES:\n- NEVER rewrite an article just to make it look fresh.\n- ONLY modify sections affected by verified new facts (e.g. date change, result declared, link active, corrigendum).\n- PRESERVE the existing structure, clarity, and tone.\n- If there are NO meaningful changes', '{\"has_meaningful_update\":true,\"update_type\":\"corrigendum\",\"change_summary\":\"NTA issued revised advisory confirming additional test center cities in Middle East for NEET UG 2026\",\"proposed_title\":\"NTA NEET UG 2026 Exam Guidelines & Overseas Center List Released\",\"proposed_excerpt\":\"NTA updates NEET UG 2026 advisory with foreign examination centers list.\",\"proposed_content\":\"<h2>Official Examination Schedule & Overseas Centers<\\/h2><p>The National Testing Agency (NTA) has officially updated the information bulletin for <strong>NEET UG 2026<\\/strong>, confirming foreign test centers across 14 international cities alongside domestic centers.<\\/p>\"}', '100', '1', NULL, '2026-08-22 04:56:45');
