INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1171', NULL, NULL, 'topic_analysis', 'Please analyze the following trend:\n\nTREND KEYWORD: Test Malformed Topic\n\nSOURCE INFORMATION:\nSource Name: Not specified\nSource URL: Not specified\nSource Snippet: Not specified\n\n\nEXISTING RELATED ARTICLES IN OUR DATABASE:\n- None\n\nReturn your response strictly as a JSON object with this exact schema:\n{\n  \"publish_recommendation\": true/false,\n  \"category\": \"category-slug-from-allowed-list\",\n  \"search_intent\": \"informational | direct_action | deadline_tracking | comparison\",\n  \"priority_score\": 85,', 'This is plain text with no JSON brackets whatsoever', '100', '1', NULL, '2026-08-22 04:56:45');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1172', NULL, NULL, 'article_generation', 'Please generate an in-depth, exhaustive, AdSense-ready editorial article (aim for 1000+ words) based strictly on the following verified information:\n\nTOPIC / HEADLINE: IBPS PO 2026 Selection Process: Prelims, Mains & Interview Score Normalization Rules\nCATEGORY: government-jobs\nEDITORIAL FOCUS: Detailed breakdown of the equipercentile normalization method in multi-shift Prelims, along with the step-by-step 80:20 Mains-to-Interview final merit list score calculation formula.\n\nVERIFIED SOURCE DATA', '', '0', '0', 'Gemini API HTTP 429 on model gemini-3.5-flash: {\n  \"error\": {\n    \"code\": 429,\n    \"message\": \"You exceeded your current quota, please check your plan and billing details. For more information on this error, head to: https://ai.google.dev/gemini-a', '2026-08-22 04:57:22');
