INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1186', NULL, NULL, 'topic_analysis', 'Please analyze the following trend:\n\nTREND KEYWORD: NTA NEET UG 2026 Examination Guidelines & Shift Timings Released\n\nSOURCE INFORMATION:\nSource Name: National Testing Agency (exams.nta.ac.in)\nSource URL: https://exams.nta.ac.in/NEET/\nSource Snippet: NTA public circular on NEET examination shifts.\n\n\nEXISTING RELATED ARTICLES IN OUR DATABASE:\n- None\n\nReturn your response strictly as a JSON object with this exact schema:\n{\n  \"publish_recommendation\": true/false,\n  \"category\": \"category-slug-from-a', '{\"publish_recommendation\":true,\"category\":\"exam-dates\",\"priority_score\":95,\"reasoning\":\"Statutory public notice from NTA regarding national NEET UG examination shift timings and security guidelines.\",\"suggested_original_angle\":\"Comprehensive candidate instructions and reporting timetable\",\"duplicate_risk\":\"low\",\"source_attribution\":{\"name\":\"National Testing Agency\",\"url\":\"https:\\/\\/exams.nta.ac.in\\/NEET\\/\",\"reference\":\"NTA\\/NEET-UG\\/2026\\/PUBLIC-NOTICE-01\"}}', '100', '1', NULL, '2026-08-22 05:02:28');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1187', NULL, NULL, 'article_generation', 'Please generate an in-depth, highly structured, AdSense-compliant editorial article (aim for 1000+ words) tailored to the topic:\n\nTOPIC / HEADLINE: NTA NEET UG 2026 Examination Guidelines & Shift Timings Released\nCATEGORY: exam-dates\nEDITORIAL FOCUS: Comprehensive candidate instructions and reporting timetable\nTODAY\'S DATE: August 22, 2026\n\nVERIFIED SOURCE DATA & TOPIC CONTEXT:\n{\n    \"keyword\": \"NTA NEET UG 2026 Examination Guidelines & Shift Timings Released\",\n    \"source_name\": \"National Testi', '{\"title\":\"NTA NEET UG 2026 Examination Guidelines & Shift Timings Released: Check Reporting Rules\",\"excerpt\":\"National Testing Agency (NTA) has officially issued comprehensive examination day instructions, shift schedules, and mandatory advisory for NEET UG 2026 aspirants.\",\"content\":\"<h2>Official Examination Schedule & Shift Timings<\\/h2><p>The National Testing Agency (NTA) has officially released the detailed information bulletin and shift timing advisory for the <strong>National Eligibility cum Entrance Test (NEET UG 2026)<\\/strong>. Over 24 lakh registered medical candidates across India and overseas centers are advised to follow official reporting hours strictly.<\\/p><h2>Crucial Examination Day Guidelines<\\/h2><ul><li><strong>Reporting Time:<\\/strong> Candidates must report at examination centers by 11:30 AM for biometric registration.<\\/li><li><strong>Admit Card & ID Proof:<\\/strong> Printed hall ticket along with original Aadhaar card or government photo ID is mandatory.<\\/li><li><strong>Prohibited Items:<\\/strong> Electronic gadgets, smartwatches, and metallic accessories are strictly prohibited inside test halls.<\\/li><\\/ul>\",\"key_takeaways\":[\"Examination date confirmed for May 03, 2026\",\"Pen and paper 