INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1270', NULL, NULL, 'seo_generation', 'Please generate SEO metadata for this article:\n\nARTICLE TITLE: NTA NEET UG 2026 Examination Guidelines & Shift Timings Released: Check Reporting Rules\nCATEGORY: exam-dates\nARTICLE CONTENT EXCERPT:\nOfficial Examination Schedule & Shift TimingsThe National Testing Agency (NTA) has officially released the detailed information bulletin and shift timing advisory for the National Eligibility cum Entrance Test (NEET UG 2026). Over 24 lakh registered medical candidates across India and overseas centers ', '{\"seo_title\":\"NEET UG 2026 Exam Guidelines & Timings Released by NTA\",\"meta_description\":\"NTA releases official NEET UG 2026 exam day guidelines, shift timings, entry rules, and barred items list. Check complete advisory at exams.nta.ac.in.\",\"slug_suggestion\":\"nta-neet-ug-2026-exam-guidelines-timings-released\",\"excerpt\":\"National Testing Agency issues mandatory examination instructions and shift schedule for NEET UG 2026.\",\"faqs\":[{\"question\":\"What is the reporting time for NEET UG 2026?\",\"answer\":\"Candidates must report to examination centers starting at 11:30 AM. Gates close strictly at 01:30 PM.\"},{\"question\":\"Which ID proofs are permitted at the examination center?\",\"answer\":\"Original Aadhaar card, Voter ID, Passport, or PAN card accompanied by the printed admit card.\"}]}', '100', '1', NULL, '2026-08-22 05:51:02');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1271', NULL, NULL, 'article_update', 'You are a senior Indian education news editor at Sarkari.online, an independent education and recruitment platform.\nWe have an existing published article that may need an incremental factual update based on new official releases.\n\nRULES:\n- NEVER rewrite an article just to make it look fresh.\n- ONLY modify sections affected by verified new facts (e.g. date change, result declared, link active, corrigendum).\n- PRESERVE the existing structure, clarity, and tone.\n- If there are NO meaningful changes', '{\"has_meaningful_update\":true,\"update_type\":\"corrigendum\",\"change_summary\":\"NTA issued revised advisory confirming additional test center cities in Middle East for NEET UG 2026\",\"proposed_title\":\"NTA NEET UG 2026 Exam Guidelines & Overseas Center List Released\",\"proposed_excerpt\":\"NTA updates NEET UG 2026 advisory with foreign examination centers list.\",\"proposed_content\":\"<h2>Official Examination Schedule & Overseas Centers<\\/h2><p>The National Testing Agency (NTA) has officially updated the information bulletin for <strong>NEET UG 2026<\\/strong>, confirming foreign test centers across 14 international cities alongside domestic centers.<\\/p>\"}', '100', '1', NULL, '2026-08-22 05:51:03');
