INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1274', NULL, NULL, 'source_verification', 'You are a strict fact-verification engine for Indian government jobs, exams, and scholarship notifications.\nToday\'s date is: 2026-08-22.\n\nARTICLE TITLE: IBPS PO 2026 Selection Process: Normalization, Merit Rules, and Exam Guide\nSOURCE AUTHORITY: Institute of Banking Personnel Selection (IBPS)\nSOURCE URL: https://ibps.in\n\nARTICLE CONTENT:\nOverview of the IBPS PO 2026 Selection ProcessThe Institute of Banking Personnel Selection (IBPS) conducts the Probationary Officer (PO) recruitment as a nation', '{\n  \"verdict\": \"fail\",\n  \"confidence\": 90,\n  \"verified_claims\": [\n    {\n      \"claim\": \"IBPS PO 2026 Official Notification\",\n      \"status\": \"contradicted\",\n      \"detail\": \"The official IBPS portal does not list an active notification for CRP PO/MT 2026 as of August 22, 2026.\"\n    },\n    {\n      \"claim\": \"IBPS PO 2026 Recruitment Timeline\",\n      \"status\": \"contradicted\",\n      \"detail\": \"The article claims a 2026 recruitment process is underway, but the official portal shows no such active recruitment cycle for PO/MT.\"\n    },\n    {\n      \"claim\": \"Conducting Body\",\n      \"status\": \"confirmed\",\n      \"detail\": \"IBPS is the correct conducting body for CRP PO/MT examinations.\"\n    }\n  ],\n  \"reason\": \"The article presents a detailed recruitment schedule and process for \'IBPS PO 2026\' which is not supported by the official IBPS portal. As of August 22, 2026, there is no official notification or active recruitment cycle for PO/MT listed on ibps.in.\"\n}', '1947', '1', NULL, '2026-08-22 05:56:28');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1275', NULL, NULL, 'topic_analysis', 'Please analyze the following trend:\n\nTREND KEYWORD: NTA NEET UG 2026 Examination Guidelines & Shift Timings Released\n\nSOURCE INFORMATION:\nSource Name: National Testing Agency (exams.nta.ac.in)\nSource URL: https://exams.nta.ac.in/NEET/\nSource Snippet: NTA public circular on NEET examination shifts.\n\n\nEXISTING RELATED ARTICLES IN OUR DATABASE:\n- None\n\nReturn your response strictly as a JSON object with this exact schema:\n{\n  \"publish_recommendation\": true/false,\n  \"category\": \"category-slug-from-a', '{\"publish_recommendation\":true,\"category\":\"exam-dates\",\"priority_score\":95,\"reasoning\":\"Statutory public notice from NTA regarding national NEET UG examination shift timings and security guidelines.\",\"suggested_original_angle\":\"Comprehensive candidate instructions and reporting timetable\",\"duplicate_risk\":\"low\",\"source_attribution\":{\"name\":\"National Testing Agency\",\"url\":\"https:\\/\\/exams.nta.ac.in\\/NEET\\/\",\"reference\":\"NTA\\/NEET-UG\\/2026\\/PUBLIC-NOTICE-01\"}}', '100', '1', NULL, '2026-08-22 05:56:34');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1276', NULL, NULL, 'article_generation', 'Please generate an in-depth, highly structured, AdSense-compliant editorial article (aim for 1000+ words) tailored to the topic:\n\nTOPIC / HEADLINE: NTA NEET UG 2026 Examination Guidelines & Shift Timings Released\nCATEGORY: exam-dates\nEDITORIAL FOCUS: Comprehensive candidate instructions and reporting timetable\nTODAY\'S DATE: August 22, 2026\n\nVERIFIED SOURCE DATA & TOPIC CONTEXT:\n{\n    \"keyword\": \"NTA NEET UG 2026 Examination Guidelines & Shift Timings Released\",\n    \"source_name\": \"National Testi', '{\"title\":\"NTA NEET UG 2026 Examination Guidelines & Shift Timings Released: Check Reporting Rules\",\"excerpt\":\"National Testing Agency (NTA) has officially issued comprehensive examination day instructions, shift schedules, and mandatory advisory for NEET UG 2026 aspirants.\",\"content\":\"<h2>Official Examination Schedule & Shift Timings<\\/h2><p>The National Testing Agency (NTA) has officially released the detailed information bulletin and shift timing advisory for the <strong>National Eligibility cum Entrance Test (NEET UG 2026)<\\/strong>. Over 24 lakh registered medical candidates across India and overseas centers are advised to follow official reporting hours strictly.<\\/p><h2>Crucial Examination Day Guidelines<\\/h2><ul><li><strong>Reporting Time:<\\/strong> Candidates must report at examination centers by 11:30 AM for biometric registration.<\\/li><li><strong>Admit Card & ID Proof:<\\/strong> Printed hall ticket along with original Aadhaar card or government photo ID is mandatory.<\\/li><li><strong>Prohibited Items:<\\/strong> Electronic gadgets, smartwatches, and metallic accessories are strictly prohibited inside test halls.<\\/li><\\/ul>\",\"key_takeaways\":[\"Examination date confirmed for May 03, 2026\",\"Pen and paper mode across all centers\",\"Mandatory biometric verification before entry\"],\"dates_table\":[{\"event\":\"Reporting Time Closes\",\"date\":\"May 03, 2026 (01:30 PM)\",\"status\":\"confirmed\"},{\"event\":\"Examination Timing\",\"date\":\"02:00 PM to 05:20 PM\",\"status\":\"confirmed\"}],\"source_attribution\":{\"name\":\"National Testing Agency\",\"url\":\"https:\\/\\/exams.nta.ac.in\\/NEET\\/\",\"reference\":\"NTA\\/NEET-UG\\/2026\\/PUBLIC-NOTICE-01\"}}', '100', '1', NULL, '2026-08-22 05:56:34');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1277', NULL, NULL, 'fact_checking', 'Please perform a rigorous factual audit on the following draft article:\n\nDRAFT ARTICLE TITLE:\nNTA NEET UG 2026 Examination Guidelines & Shift Timings Released: Check Reporting Rules\n\nDRAFT ARTICLE CONTENT:\nOfficial Examination Schedule & Shift TimingsThe National Testing Agency (NTA) has officially released the detailed information bulletin and shift timing advisory for the National Eligibility cum Entrance Test (NEET UG 2026). Over 24 lakh registered medical candidates across India and overseas', '{\"overall_score\":98,\"factual_accuracy_score\":99,\"dates_accuracy_score\":98,\"source_consistency_score\":98,\"hallucination_risk\":\"low\",\"copied_risk\":\"low\",\"recommendation\":\"pass\",\"flagged_issues\":[],\"summary\":\"All guidelines, timings, and official NTA public circular references verified accurate.\"}', '100', '1', NULL, '2026-08-22 05:56:36');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1278', NULL, NULL, 'content_editing', 'Please polish and editorially enhance this draft article:\n\nHEADLINE: NTA NEET UG 2026 Examination Guidelines & Shift Timings Released: Check Reporting Rules\nCATEGORY: exam-dates\n\nRAW CONTENT:\n<h2>Official Examination Schedule & Shift Timings</h2><p>The National Testing Agency (NTA) has officially released the detailed information bulletin and shift timing advisory for the <strong>National Eligibility cum Entrance Test (NEET UG 2026)</strong>. Over 24 lakh registered medical candidates across Ind', '{\"edited_title\":\"NTA NEET UG 2026 Examination Guidelines & Shift Timings Released: Check Reporting Rules\",\"edited_content\":\"<h2>Official Examination Schedule & Shift Timings<\\/h2><p>The National Testing Agency (NTA) has officially released the detailed information bulletin and shift timing advisory for the <strong>National Eligibility cum Entrance Test (NEET UG 2026)<\\/strong>. Over 24 lakh registered medical candidates across India and overseas centers are advised to follow official reporting hours strictly.<\\/p><h2>Crucial Examination Day Guidelines<\\/h2><ul><li><strong>Reporting Time:<\\/strong> Candidates must report at examination centers by 11:30 AM for biometric registration.<\\/li><li><strong>Admit Card & ID Proof:<\\/strong> Printed hall ticket along with original Aadhaar card or government photo ID is mandatory.<\\/li><li><strong>Prohibited Items:<\\/strong> Electronic gadgets, smartwatches, and metallic accessories are strictly prohibited inside test halls.<\\/li><\\/ul>\",\"readability_score\":95,\"improvements_made\":[\"Structured bullet points for examination day rules\",\"Enhanced lead paragraph readability\"]}', '100', '1', NULL, '2026-08-22 05:56:39');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1279', NULL, NULL, 'seo_generation', 'Please generate SEO metadata for this article:\n\nARTICLE TITLE: NTA NEET UG 2026 Examination Guidelines & Shift Timings Released: Check Reporting Rules\nCATEGORY: exam-dates\nARTICLE CONTENT EXCERPT:\nOfficial Examination Schedule & Shift TimingsThe National Testing Agency (NTA) has officially released the detailed information bulletin and shift timing advisory for the National Eligibility cum Entrance Test (NEET UG 2026). Over 24 lakh registered medical candidates across India and overseas centers ', '{\"seo_title\":\"NEET UG 2026 Exam Guidelines & Timings Released by NTA\",\"meta_description\":\"NTA releases official NEET UG 2026 exam day guidelines, shift timings, entry rules, and barred items list. Check complete advisory at exams.nta.ac.in.\",\"slug_suggestion\":\"nta-neet-ug-2026-exam-guidelines-timings-released\",\"excerpt\":\"National Testing Agency issues mandatory examination instructions and shift schedule for NEET UG 2026.\",\"faqs\":[{\"question\":\"What is the reporting time for NEET UG 2026?\",\"answer\":\"Candidates must report to examination centers starting at 11:30 AM. Gates close strictly at 01:30 PM.\"},{\"question\":\"Which ID proofs are permitted at the examination center?\",\"answer\":\"Original Aadhaar card, Voter ID, Passport, or PAN card accompanied by the printed admit card.\"}]}', '100', '1', NULL, '2026-08-22 05:56:44');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1280', NULL, NULL, 'article_update', 'You are a senior Indian education news editor at Sarkari.online, an independent education and recruitment platform.\nWe have an existing published article that may need an incremental factual update based on new official releases.\n\nRULES:\n- NEVER rewrite an article just to make it look fresh.\n- ONLY modify sections affected by verified new facts (e.g. date change, result declared, link active, corrigendum).\n- PRESERVE the existing structure, clarity, and tone.\n- If there are NO meaningful changes', '{\"has_meaningful_update\":true,\"update_type\":\"corrigendum\",\"change_summary\":\"NTA issued revised advisory confirming additional test center cities in Middle East for NEET UG 2026\",\"proposed_title\":\"NTA NEET UG 2026 Exam Guidelines & Overseas Center List Released\",\"proposed_excerpt\":\"NTA updates NEET UG 2026 advisory with foreign examination centers list.\",\"proposed_content\":\"<h2>Official Examination Schedule & Overseas Centers<\\/h2><p>The National Testing Agency (NTA) has officially updated the information bulletin for <strong>NEET UG 2026<\\/strong>, confirming foreign test centers across 14 international cities alongside domestic centers.<\\/p>\"}', '100', '1', NULL, '2026-08-22 05:56:44');
