INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1427', NULL, NULL, 'seo_generation', 'Please generate SEO metadata for this article:\n\nARTICLE TITLE: Post Matric Scholarship 2026: Income Limits, Eligibility, and Application Guide\nCATEGORY: scholarships\nARTICLE CONTENT EXCERPT:\nOverview of the Post Matric Scholarship Scheme 2026The Post Matric Scholarship (PMS) is a flagship initiative by the Ministry of Social Justice and Empowerment, Government of India. It provides financial assistance to students from Scheduled Castes (SC), Scheduled Tribes (ST), and Other Backward Classes (OBC', '{\n  \"seo_title\": \"Post Matric Scholarship 2026: Eligibility & Apply Guide\",\n  \"meta_description\": \"Check Post Matric Scholarship 2026 eligibility, income limits, and application steps. Apply via the National Scholarship Portal for financial aid today.\",\n  \"slug_suggestion\": \"post-matric-scholarship-2026-application-guide\",\n  \"excerpt\": \"Learn about the Post Matric Scholarship 2026 eligibility criteria, income limits, and the step-by-step application process via the National Scholarship Portal.\",\n  \"target_keywords\": [\n    \"Post Matric Scholarship 2026\",\n    \"PMS scholarship eligibility 2026\",\n    \"NSP scholarship registration 2026\",\n    \"Post Matric Scholarship income limit\",\n    \"how to apply for Post Matric Scholarship\",\n    \"SC ST OBC scholarship 2026\",\n    \"National Scholarship Portal guide\"\n  ],\n  \"faqs\": [\n    {\n      \"question\": \"Can I apply for both State and Central scholarships simultaneously?\",\n      \"answer\": \"No, students are eligible to receive only one scholarship at a time. Applying for multiple schemes may lead to the rejection of your application.\"\n    },\n    {\n      \"question\": \"What is the maximum annual family income limit for the 2026 scholarship?\",\n      \"answer\": \"For the 2026-27 academic year, the annual family income limit for SC, ST, and OBC category students is set at Rs 2.50 Lakhs.\"\n    }\n  ]\n}', '1308', '1', NULL, '2026-08-22 07:10:23');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1428', NULL, NULL, 'source_verification', 'You are a senior editorial audit engine for an Indian education and career portal.\nToday\'s date is: 2026-08-22.\n\nARTICLE TITLE: SSC GD Constable 2026: Exam Pattern, Physical Standards & Preparation Guide\nAUTHORITY: Staff Selection Commission (SSC)\nSOURCE URL: https://ssc.gov.in\n\nARTICLE CONTENT:\nOverview of SSC GD Constable 2026 RecruitmentThe Staff Selection Commission (SSC) conducts the General Duty (GD) Constable recruitment for various Central Armed Police Forces (CAPFs), including the BSF, ', '{\n  \"verdict\": \"fail\",\n  \"confidence\": 90,\n  \"verified_points\": [\n    {\n      \"point\": \"Exam structure accuracy\",\n      \"status\": \"failed\",\n      \"note\": \"The article incorrectly states the CBE consists of 80 questions with 25% weightage per section. The actual SSC GD pattern consists of 80 questions total, but the distribution is 20 questions per section (General Intelligence, GK, Math, English/Hindi), not 25% weightage per section as implied by the structure.\"\n    },\n    {\n      \"point\": \"Negative marking accuracy\",\n      \"status\": \"confirmed\",\n      \"note\": \"The negative marking of 0.50 marks for a 2-mark question is consistent with current SSC GD standards.\"\n    },\n    {\n      \"point\": \"Physical standards accuracy\",\n      \"status\": \"confirmed\",\n      \"note\": \"The PET/PST metrics provided align with standard SSC GD recruitment guidelines.\"\n    },\n    {\n      \"point\": \"Content integrity\",\n      \"status\": \"failed\",\n      \"note\": \"The article includes irrelevant cross-promotional links to \'CBSE CTET 2026\' which is a teacher eligibility test, creating confusion in a specialized recruitment guide.\"\n    }\n  ],\n  \"reason\": \"While the physical standards and negative marking are accurate, the article misrepresents the exam section distribution (claiming 25% weightage per section rather than 20 questions per section) and includes irrelevant external exam references that dilute the quality of the educational guidance.\"\n}', '1384', '1', NULL, '2026-08-22 07:10:30');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1429', NULL, NULL, 'source_verification', 'You are a senior editorial audit engine for an Indian education and career portal.\nToday\'s date is: 2026-08-22.\n\nARTICLE TITLE: JEE Main 2027: Syllabus Overview and Chapter-wise Weightage Analysis\nAUTHORITY: National Testing Agency (NTA)\nSOURCE URL: https://jeemain.nta.ac.in\n\nARTICLE CONTENT:\nOverview of JEE Main 2027 PreparationAs of August 22, 2026, students targeting the JEE Main 2027 examination are entering a critical preparation phase. The National Testing Agency (NTA) maintains a syllabus', '{\n  \"verdict\": \"pass\",\n  \"confidence\": 95,\n  \"verified_points\": [\n    {\n      \"point\": \"Exam structure accuracy\",\n      \"status\": \"confirmed\",\n      \"note\": \"The article correctly identifies the NTA as the governing body and acknowledges the alignment with NCERT, avoiding the fabrication of specific exam duration or marking schemes which are subject to annual notification.\"\n    },\n    {\n      \"point\": \"Weightage transparency\",\n      \"status\": \"confirmed\",\n      \"note\": \"The article explicitly clarifies that weightage is based on historical trend analysis and explicitly states that the NTA does not mandate fixed chapter-wise weightage.\"\n    },\n    {\n      \"point\": \"Temporal relevance\",\n      \"status\": \"confirmed\",\n      \"note\": \"The content is tailored for the 2027 cycle, referencing 2023-2026 as historical data, which is accurate for the current date of August 2026.\"\n    },\n    {\n      \"point\": \"Educational guidance quality\",\n      \"status\": \"confirmed\",\n      \"note\": \"The advice provided (NCERT mastery, PYQ practice, and mock tests) aligns with standard pedagogical recommendations for JEE Main preparation.\"\n    }\n  ],\n  \"reason\": \"The article maintains high editorial integrity by correctly distinguishing between official NTA syllabus guidelines and historical trend analysis. It avoids making false claims regarding statutory question distribution and provides sound, actionable advice for the 2027 examination cycle.\"\n}', '1283', '1', NULL, '2026-08-22 07:10:35');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1430', NULL, NULL, 'source_verification', 'You are a strict fact-verification engine for Indian government jobs, exams, and scholarship notifications.\nToday\'s date is: 2026-08-22.\n\nARTICLE TITLE: CBSE Class 10 & 12 Sample Papers 2027: Official Marking Schemes Released\nSOURCE AUTHORITY: Central Board of Secondary Education (CBSE)\nSOURCE URL: https://cbseacademic.nic.in\n\nARTICLE CONTENT:\nOverview of CBSE 2027 Sample Question PapersThe Central Board of Secondary Education (CBSE) has released the Sample Question Papers (SQPs) and detailed Ma', '{\n  \"verdict\": \"fail\",\n  \"confidence\": 95,\n  \"verified_claims\": [\n    {\n      \"claim\": \"CBSE has released Sample Question Papers (SQPs) and Marking Schemes for the 2027 Board Examinations.\",\n      \"status\": \"contradicted\",\n      \"detail\": \"The official CBSE academic portal (cbseacademic.nic.in) currently lists SQP 2025-2026 as the latest available sample papers. There is no official notification or link for 2027 Sample Question Papers.\"\n    },\n    {\n      \"claim\": \"CBSE Board Exam 2027 Date Sheet Released.\",\n      \"status\": \"contradicted\",\n      \"detail\": \"There is no official announcement or publication of the 2027 Board Exam date sheet on the CBSE academic portal.\"\n    }\n  ],\n  \"reason\": \"The article makes false claims regarding the release of 2027 Sample Question Papers and the 2027 Board Exam date sheet. The official CBSE portal currently only provides resources up to the 2025-2026 academic cycle.\"\n}', '2252', '1', NULL, '2026-08-22 07:10:40');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1431', NULL, NULL, 'source_verification', 'You are a strict fact-verification engine for Indian government jobs, exams, and scholarship notifications.\nToday\'s date is: 2026-08-22.\n\nARTICLE TITLE: SSC MTS & Havaldar 2026: Official Notification, Eligibility, and Selection Guide\nSOURCE AUTHORITY: Staff Selection Commission (SSC)\nSOURCE URL: https://ssc.gov.in\n\nARTICLE CONTENT:\nOverview of SSC MTS and Havaldar Recruitment 2026The Staff Selection Commission (SSC) has launched the 2026 recruitment cycle for Multi-Tasking (Non-Technical) Staff ', '{\n  \"verdict\": \"pass\",\n  \"confidence\": 90,\n  \"verified_claims\": [\n    {\n      \"claim\": \"SSC MTS & Havaldar 2026 recruitment cycle\",\n      \"status\": \"confirmed\",\n      \"detail\": \"The article correctly identifies the 2026 cycle and the conducting body as the Staff Selection Commission.\"\n    },\n    {\n      \"claim\": \"Mandatory OTR on ssc.gov.in\",\n      \"status\": \"confirmed\",\n      \"detail\": \"SSC has transitioned to the new portal (ssc.gov.in) and made OTR mandatory for all candidates.\"\n    },\n    {\n      \"claim\": \"Educational Qualification: Matriculation (Class 10)\",\n      \"status\": \"confirmed\",\n      \"detail\": \"Standard eligibility for SSC MTS and Havaldar remains Class 10 pass.\"\n    },\n    {\n      \"claim\": \"PET/PST for Havaldar is qualifying in nature\",\n      \"status\": \"confirmed\",\n      \"detail\": \"Physical tests for Havaldar are qualifying and do not contribute to the final merit list.\"\n    },\n    {\n      \"claim\": \"Examination Pattern (Session I and II)\",\n      \"status\": \"confirmed\",\n      \"detail\": \"The structure of Session I (no negative marking) and Session II (negative marking) aligns with the current SSC MTS exam pattern.\"\n    }\n  ],\n  \"reason\": \"The article accurately reflects the current recruitment procedures, the mandatory OTR system on the new SSC portal, and the standard eligibility and examination criteria for the SSC MTS and Havaldar 2026 cycle.\"\n}', '1348', '1', NULL, '2026-08-22 07:10:46');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1432', NULL, NULL, 'source_verification', 'You are a strict fact-verification engine for Indian government jobs, exams, and scholarship notifications.\nToday\'s date is: 2026-08-22.\n\nARTICLE TITLE: RRB Group D 2026: PET Standards and Selection Guidelines\nSOURCE AUTHORITY: Railway Recruitment Control Board (RRB)\nSOURCE URL: https://rrbcdg.gov.in\n\nARTICLE CONTENT:\nOverview of RRB Group D 2026 Selection ProcessThe Railway Recruitment Board (RRB) Level 1 recruitment follows a multi-stage process. After the Computer Based Test (CBT), shortliste', '{\n  \"verdict\": \"fail\",\n  \"confidence\": 30,\n  \"verified_claims\": [\n    {\n      \"claim\": \"RRB Group D 2026 recruitment notification\",\n      \"status\": \"contradicted\",\n      \"detail\": \"There is no official notification for RRB Group D 2026 published on the official RRB Chandigarh portal as of August 22, 2026.\"\n    },\n    {\n      \"claim\": \"PET standards for RRB Group D\",\n      \"status\": \"confirmed\",\n      \"detail\": \"The physical standards mentioned (35kg/20kg weight carry and running times) align with historical RRB Group D recruitment norms.\"\n    },\n    {\n      \"claim\": \"Source authority and URL\",\n      \"status\": \"contradicted\",\n      \"detail\": \"The provided URL redirects to a generic landing page and does not contain the specific 2026 recruitment notification described in the article.\"\n    }\n  ],\n  \"reason\": \"While the physical standards listed are consistent with historical RRB Group D norms, the article presents a specific 2026 recruitment notification that does not exist on the official RRB Chandigarh portal. The content appears to be a fabricated or speculative notification rather than an official government release.\"\n}', '1205', '1', NULL, '2026-08-22 07:10:51');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1433', NULL, NULL, 'article_generation', 'Please generate an in-depth, highly structured, AdSense-compliant editorial article (aim for 1000+ words) tailored to the topic:\n\nTOPIC / HEADLINE: SBI PO 2026 Prelims & Mains Syllabus, Sectional Cutoff Rules and Group Exercise Pattern\nCATEGORY: government-jobs\nEDITORIAL FOCUS: A detailed breakdown of the SBI PO 2026 selection process, specifically focusing on the nuances of the Group Exercise and Interview phase, which differentiates it from other banking exams like IBPS PO.\nTODAY\'S DATE: Augus', '{\n  \"title\": \"SBI PO 2026: Syllabus, Cutoff Rules and Group Exercise Guide\",\n  \"excerpt\": \"Master the SBI PO 2026 selection process with our comprehensive guide on syllabus, sectional cutoffs, and the unique Group Exercise and Interview phase.\",\n  \"content\": \"<h2>Overview of the SBI PO 2026 Selection Process</h2><p>The State Bank of India (SBI) Probationary Officer (PO) recruitment is widely regarded as one of the most prestigious and challenging banking examinations in India. As of August 22, 2026, aspirants must understand that the selection process is divided into three distinct phases: Preliminary Examination, Main Examination (Objective and Descriptive), and the Psychometric Test followed by the Group Exercise and Interview. Unlike other banking exams, SBI maintains a unique structure that tests not just academic aptitude but also leadership and interpersonal skills.</p><h2>Phase I: Preliminary Examination Pattern</h2><p>The Preliminary Examination is a qualifying round. Marks obtained here are not added to the final merit list. The exam consists of 100 objective-type questions to be completed in 60 minutes.</p><table><thead><tr><th>Section</th><th>Number of Questions</th><th>Marks</th><th>Duration</th></tr></thead><tbody><tr><td>English Language</td><td>30</td><td>30</td><td>20 Minutes</td></tr><tr><td>Quantitative Aptitude</td><td>35</td><td>35</td><td>20 Minutes</td></tr><tr><td>Reasoning Ability</td><td>35</td><td>35</td><td>20 Minutes</td></tr></tbody></table><p><em>Note: There is a penalty of 0.25 marks for every incorrect answer. Sectional cutoffs are determined by the bank based on the difficulty level and performance of the candidate pool.</em></p><h2>Phase II: Main Examination Syllabus and Structure</h2><p>The Main Examination is the most critical stage. It consists of an Objective Test (200 marks) and a Descriptive Test (50 marks). The Objective Test includes a sectional timing component.</p><h3>Trend-Based Historical Distribution (Based on Past Exam', '2641', '1', NULL, '2026-08-22 07:11:50');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1434', NULL, NULL, 'fact_checking', 'Please perform a rigorous factual audit on the following draft article:\n\nDRAFT ARTICLE TITLE:\nSBI PO 2026: Syllabus, Cutoff Rules and Group Exercise Guide\n\nDRAFT ARTICLE CONTENT:\nOverview of the SBI PO 2026 Selection ProcessThe State Bank of India (SBI) Probationary Officer (PO) recruitment is widely regarded as one of the most prestigious and challenging banking examinations in India. As of August 22, 2026, aspirants must understand that the selection process is divided into three distinct phas', '{\n  \"overall_score\": 92,\n  \"factual_accuracy_score\": 95,\n  \"dates_accuracy_score\": 100,\n  \"source_consistency_score\": 90,\n  \"hallucination_risk\": \"low\",\n  \"copied_risk\": \"low\",\n  \"recommendation\": \"pass\",\n  \"flagged_issues\": [\n    {\n      \"claim\": \"As of August 22, 2026, aspirants must understand that the selection process is divided into three distinct phases\",\n      \"issue_type\": \"unsupported_claim\",\n      \"severity\": \"minor\",\n      \"correction_advice\": \"Since the official 2026 notification has not been released by SBI, frame this as \'based on the established selection pattern\' rather than implying a specific date of current status.\"\n    },\n    {\n      \"claim\": \"The final merit list is prepared based on the marks obtained in the Main Examination (Objective + Descriptive) and the Group Exercise/Interview phase, normalized to a total of 100 marks.\",\n      \"issue_type\": \"unsupported_claim\",\n      \"severity\": \"minor\",\n      \"correction_advice\": \"Clarify that the normalization ratio (typically 75:25 for Mains and GE/Interview) is subject to the official notification, as the bank reserves the right to adjust weightage.\"\n    }\n  ],\n  \"summary\": \"The article is highly accurate and aligns well with the established SBI PO recruitment framework. It correctly identifies the three-phase structure and the specific inclusion of the Psychometric Test and Group Exercise. Minor adjustments are recommended to ensure the language reflects that the 2026 notification is pending, avoiding definitive statements on future policy.\"\n}', '1942', '1', NULL, '2026-08-22 07:11:55');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1435', NULL, NULL, 'content_editing', 'Please polish and editorially enhance this draft article:\n\nHEADLINE: SBI PO 2026: Syllabus, Cutoff Rules and Group Exercise Guide\nCATEGORY: government-jobs\n\nRAW CONTENT:\n<h2>Overview of the SBI PO 2026 Selection Process</h2><p>The State Bank of India (SBI) Probationary Officer (PO) recruitment is widely regarded as one of the most prestigious and challenging banking examinations in India. As of August 22, 2026, aspirants must understand that the selection process is divided into three distinct p', '{\n  \"edited_title\": \"SBI PO 2026: Complete Syllabus, Selection Process, and Exam Guide\",\n  \"edited_content\": \"<h2>Overview of the SBI PO 2026 Selection Process</h2><p>The State Bank of India (SBI) Probationary Officer (PO) recruitment is a premier banking examination in India. As of August 22, 2026, the selection process consists of three distinct phases designed to test academic aptitude, leadership, and interpersonal skills.</p><h2>Phase I: Preliminary Examination</h2><p>The Preliminary Examination is a qualifying round; marks are not added to the final merit list. The exam consists of 100 objective-type questions to be completed in 60 minutes.</p><table><thead><tr><th>Section</th><th>Questions</th><th>Marks</th><th>Duration</th></tr></thead><tbody><tr><td>English Language</td><td>30</td><td>30</td><td>20 Min</td></tr><tr><td>Quantitative Aptitude</td><td>35</td><td>35</td><td>20 Min</td></tr><tr><td>Reasoning Ability</td><td>35</td><td>35</td><td>20 Min</td></tr></tbody></table><p><strong>Note:</strong> A penalty of 0.25 marks applies for every incorrect answer. Sectional cutoffs are determined by the bank based on candidate performance.</p><h2>Phase II: Main Examination</h2><p>The Main Examination comprises an Objective Test (200 marks) and a Descriptive Test (50 marks) with sectional timing.</p><h3>Historical Topic Weightage</h3><table><thead><tr><th>Subject</th><th>Key Topics</th><th>Weightage</th></tr></thead><tbody><tr><td>Reasoning & Computer Aptitude</td><td>Puzzles, Seating Arrangement, Syllogism</td><td>40-45%</td></tr><tr><td>Data Analysis & Interpretation</td><td>DI, Caselets, Charts</td><td>35-40%</td></tr><tr><td>General/Banking Awareness</td><td>Current Affairs, Financial News</td><td>30-35%</td></tr><tr><td>English Language</td><td>Reading Comprehension, Cloze Test</td><td>20-25%</td></tr></tbody></table><p><em>Disclaimer: Weightage is based on historical trends and is not officially prescribed by the bank.</em></p><h2>Phase III: Psychometric Test,', '2338', '1', NULL, '2026-08-22 07:12:01');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1436', NULL, NULL, 'internal_linking', 'Please contextualize internal links in the following article content:\n\nARTICLE CONTENT (HTML):\n<h2>Overview of the SBI PO 2026 Selection Process</h2><p>The State Bank of India (SBI) Probationary Officer (PO) recruitment is a premier banking examination in India. As of August 22, 2026, the selection process consists of three distinct phases designed to test academic aptitude, leadership, and interpersonal skills.</p><h2>Phase I: Preliminary Examination</h2><p>The Preliminary Examination is a qual', '{\n  \"linked_content\": \"<h2>Overview of the SBI PO 2026 Selection Process</h2><p>The State Bank of India (SBI) Probationary Officer (PO) recruitment is a premier banking examination in India. As of August 22, 2026, the selection process consists of three distinct phases designed to test academic aptitude, leadership, and interpersonal skills. For candidates exploring other major competitive opportunities, the <a href=\'/automation/article/ssc-cgl-2026-notification-apply/\'>SSC CGL 2026 Notification</a> provides details on another highly sought-after government recruitment.</p><h2>Phase I: Preliminary Examination</h2><p>The Preliminary Examination is a qualifying round; marks are not added to the final merit list. The exam consists of 100 objective-type questions to be completed in 60 minutes.</p><table><thead><tr><th>Section</th><th>Questions</th><th>Marks</th><th>Duration</th></tr></thead><tbody><tr><td>English Language</td><td>30</td><td>30</td><td>20 Min</td></tr><tr><td>Quantitative Aptitude</td><td>35</td><td>35</td><td>20 Min</td></tr><tr><td>Reasoning Ability</td><td>35</td><td>35</td><td>20 Min</td></tr></tbody></table><p><strong>Note:</strong> A penalty of 0.25 marks applies for every incorrect answer. Sectional cutoffs are determined by the bank based on candidate performance. If you are also preparing for other banking roles, you may want to check the <a href=\'/automation/article/ibps-po-2026-prelims-admit-card-download-active/\'>IBPS PO 2026 Prelims Admit Card</a> status.</p><h2>Phase II: Main Examination</h2><p>The Main Examination comprises an Objective Test (200 marks) and a Descriptive Test (50 marks) with sectional timing.</p><h3>Historical Topic Weightage</h3><table><thead><tr><th>Subject</th><th>Key Topics</th><th>Weightage</th></tr></thead><tbody><tr><td>Reasoning & Computer Aptitude</td><td>Puzzles, Seating Arrangement, Syllogism</td><td>40-45%</td></tr><tr><td>Data Analysis & Interpretation</td><td>DI, Caselets, Charts</td><td>35-40%</td></tr><tr><', '2740', '1', NULL, '2026-08-22 07:12:07');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1437', NULL, NULL, 'seo_generation', 'Please generate SEO metadata for this article:\n\nARTICLE TITLE: SBI PO 2026: Complete Syllabus, Selection Process, and Exam Guide\nCATEGORY: government-jobs\nARTICLE CONTENT EXCERPT:\nOverview of the SBI PO 2026 Selection ProcessThe State Bank of India (SBI) Probationary Officer (PO) recruitment is a premier banking examination in India. As of August 22, 2026, the selection process consists of three distinct phases designed to test academic aptitude, leadership, and interpersonal skills. For candida', '{\n  \"seo_title\": \"SBI PO 2026: Syllabus, Selection Process & Exam Guide\",\n  \"meta_description\": \"Master the SBI PO 2026 exam with our complete guide on syllabus, selection stages, and preparation tips. Start your banking career journey today.\",\n  \"slug_suggestion\": \"sbi-po-2026-syllabus-selection-process\",\n  \"excerpt\": \"Get a comprehensive breakdown of the SBI PO 2026 selection process, exam pattern, syllabus, and expert preparation strategies for your success.\",\n  \"target_keywords\": [\n    \"SBI PO 2026 syllabus\",\n    \"SBI PO selection process 2026\",\n    \"SBI PO exam pattern\",\n    \"how to prepare for SBI PO\",\n    \"SBI PO eligibility criteria\",\n    \"SBI PO descriptive test tips\"\n  ],\n  \"faqs\": [\n    {\n      \"question\": \"Are the marks from the SBI PO Preliminary Examination added to the final merit list?\",\n      \"answer\": \"No, the Preliminary Examination is only a qualifying round, and its marks are not considered for the final merit list.\"\n    },\n    {\n      \"question\": \"What is the purpose of the Psychometric Test in the SBI PO selection process?\",\n      \"answer\": \"The Psychometric Test is a personality profiling tool used to provide insights to the interview panel; it does not carry any direct marks.\"\n    }\n  ]\n}', '1327', '1', NULL, '2026-08-22 07:12:11');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1438', NULL, NULL, 'article_generation', 'Please generate an in-depth, highly structured, AdSense-compliant editorial article (aim for 1000+ words) tailored to the topic:\n\nTOPIC / HEADLINE: RRB Assistant Loco Pilot (ALP) 2026: CBT 1 & CBT 2 Exam Pattern and Psycho Test Guide\nCATEGORY: government-jobs\nEDITORIAL FOCUS: A detailed breakdown of the RRB ALP 2026 selection process, specifically focusing on the transition from CBT 1 to CBT 2 and the technical nuances of the Computer Based Aptitude Test (CBAT/Psycho Test) to help candidates pre', '{\n  \"title\": \"RRB ALP 2026: CBT 1, CBT 2 and Psycho Test Exam Pattern Guide\",\n  \"excerpt\": \"Master the RRB ALP 2026 selection process with our comprehensive guide on CBT 1, CBT 2, and the Computer Based Aptitude Test (CBAT) requirements.\",\n  \"content\": \"<h2>Overview of the RRB ALP 2026 Selection Process</h2><p>The Railway Recruitment Board (RRB) Assistant Loco Pilot (ALP) examination is a multi-stage recruitment process designed to test a candidate\'s technical aptitude, logical reasoning, and psychological readiness. As of August 22, 2026, candidates preparing for the current cycle must understand that the selection is divided into three distinct Computer Based Tests (CBTs) followed by Document Verification and Medical Examination. Success in this examination requires a strategic approach to both the technical syllabus and the specialized Psycho Test.</p><h2>CBT 1: The Screening Stage</h2><p>CBT 1 serves as a screening test to shortlist candidates for the subsequent stages. It is objective in nature and focuses on general intelligence and basic science. The marks obtained in CBT 1 are not counted toward the final merit list; however, qualifying is mandatory.</p><table><thead><tr><th>Subject</th><th>Number of Questions</th><th>Duration</th></tr></thead><tbody><tr><td>Mathematics</td><td>20</td><td>60 Minutes</td></tr><tr><td>General Intelligence & Reasoning</td><td>25</td><td>60 Minutes</td></tr><tr><td>General Science</td><td>20</td><td>60 Minutes</td></tr><tr><td>General Awareness</td><td>10</td><td>60 Minutes</td></tr></tbody></table><p><em>Note: There is a negative marking of 1/3rd for every incorrect answer.</em></p><h2>CBT 2: The Technical Core</h2><p>CBT 2 is the most critical stage for merit determination. It is divided into two parts: Part A and Part B. Part A covers core subjects, while Part B is a qualifying test based on the candidate\'s specific ITI/Trade discipline.</p><h3>Part A Breakdown</h3><ul><li>Mathematics: 25 Questions</li><li>General Intelligenc', '2512', '1', NULL, '2026-08-22 07:12:21');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1439', NULL, NULL, 'fact_checking', 'Please perform a rigorous factual audit on the following draft article:\n\nDRAFT ARTICLE TITLE:\nRRB ALP 2026: CBT 1, CBT 2 and Psycho Test Exam Pattern Guide\n\nDRAFT ARTICLE CONTENT:\nOverview of the RRB ALP 2026 Selection ProcessThe Railway Recruitment Board (RRB) Assistant Loco Pilot (ALP) examination is a multi-stage recruitment process designed to test a candidate\'s technical aptitude, logical reasoning, and psychological readiness. As of August 22, 2026, candidates preparing for the current cyc', '{\n  \"overall_score\": 85,\n  \"factual_accuracy_score\": 85,\n  \"dates_accuracy_score\": 90,\n  \"source_consistency_score\": 80,\n  \"hallucination_risk\": \"medium\",\n  \"copied_risk\": \"low\",\n  \"recommendation\": \"needs_review\",\n  \"flagged_issues\": [\n    {\n      \"claim\": \"CBT 1: Subject Mathematics 20, General Intelligence & Reasoning 25, General Science 20, General Awareness 10 (60 Minutes total)\",\n      \"issue_type\": \"unsupported_claim\",\n      \"severity\": \"critical\",\n      \"correction_advice\": \"The standard RRB ALP CBT 1 pattern consists of 75 questions to be solved in 60 minutes. The distribution is: Mathematics (20), General Intelligence & Reasoning (25), General Science (20), and General Awareness/Current Affairs (10). The draft incorrectly implies each section has a 60-minute duration, which is factually incorrect; the total duration for all 75 questions is 60 minutes.\"\n    },\n    {\n      \"claim\": \"Part A Breakdown: Mathematics: 25, General Intelligence & Reasoning: 25, Basic Science & Engineering: 40, General Awareness & Current Affairs: 10\",\n      \"issue_type\": \"unsupported_claim\",\n      \"severity\": \"critical\",\n      \"correction_advice\": \"The standard RRB ALP CBT 2 Part A consists of 100 questions total. The breakdown is: Mathematics (25), General Intelligence & Reasoning (25), Basic Science & Engineering (40), and General Awareness & Current Affairs (10). While the numbers are correct, the total sum is 100, not 100 as implied by the list structure. Ensure clarity that the total duration is 90 minutes.\"\n    }\n  ],\n  \"summary\": \"The article provides a generally accurate structure of the RRB ALP selection process. However, it contains a critical error regarding the CBT 1 exam duration, incorrectly suggesting each subject has a 60-minute limit rather than a total of 60 minutes for the entire paper. The content requires minor revisions to clarify time constraints and total question counts to avoid misleading candidates.\"\n}', '1981', '1', NULL, '2026-08-22 07:12:27');
INSERT INTO `ai_logs` (`id`, `article_id`, `trend_id`, `pipeline_stage`, `prompt_summary`, `response_summary`, `tokens_used`, `success`, `error_message`, `created_at`) VALUES ('1440', NULL, NULL, 'content_editing', 'Please polish and editorially enhance this draft article:\n\nHEADLINE: RRB ALP 2026: CBT 1, CBT 2 and Psycho Test Exam Pattern Guide\nCATEGORY: government-jobs\n\nRAW CONTENT:\n<h2>Overview of the RRB ALP 2026 Selection Process</h2><p>The Railway Recruitment Board (RRB) Assistant Loco Pilot (ALP) examination is a multi-stage recruitment process designed to test a candidate\'s technical aptitude, logical reasoning, and psychological readiness. As of August 22, 2026, candidates preparing for the current ', '{\n  \"edited_title\": \"RRB ALP 2026: Complete Exam Pattern Guide for CBT 1, CBT 2, and Psycho Test\",\n  \"edited_content\": \"<h2>Overview of the RRB ALP 2026 Selection Process</h2><p>The Railway Recruitment Board (RRB) Assistant Loco Pilot (ALP) examination is a multi-stage process testing technical aptitude, reasoning, and psychological readiness. As of August 22, 2026, the selection consists of three Computer Based Tests (CBTs), followed by Document Verification and Medical Examination.</p><h2>CBT 1: Screening Stage</h2><p>CBT 1 is a mandatory qualifying test. Marks obtained here are not included in the final merit list.</p><table><thead><tr><th>Subject</th><th>Questions</th><th>Duration</th></tr></thead><tbody><tr><td>Mathematics</td><td>20</td><td>60 Minutes</td></tr><tr><td>General Intelligence & Reasoning</td><td>25</td><td>60 Minutes</td></tr><tr><td>General Science</td><td>20</td><td>60 Minutes</td></tr><tr><td>General Awareness</td><td>10</td><td>60 Minutes</td></tr></tbody></table><p><strong>Note:</strong> A negative marking of 1/3rd applies to every incorrect answer.</p><h2>CBT 2: Technical Core</h2><p>CBT 2 determines the final merit and is divided into two parts.</p><h3>Part A: Merit-Based</h3><ul><li>Mathematics: 25 Questions</li><li>General Intelligence & Reasoning: 25 Questions</li><li>Basic Science & Engineering: 40 Questions</li><li>General Awareness & Current Affairs: 10 Questions</li></ul><h3>Part B: Qualifying Trade Test</h3><p>Part B is specific to your ITI/Trade discipline. Candidates must secure a minimum of 35% marks to qualify. Failure to pass Part B results in immediate disqualification, regardless of your score in Part A.</p><h2>Computer Based Aptitude Test (CBAT / Psycho Test)</h2><p>The CBAT evaluates cognitive abilities such as memory, observation, and spatial perception. There is no negative marking in this stage. Candidates must achieve a minimum T-score of 42 in each test battery.</p><h3>CBAT Components</h3><ol><li><strong>Memory Test:</', '2084', '1', NULL, '2026-08-22 07:12:33');
